mapper.select:
SELECT COUNT(*)
FROM wechat_event
WHERE effective_occurred_at >= #{s}
  AND effective_occurred_at < #{e}
  AND received_at < #{cutoff}

SELECT COUNT(DISTINCT open_id)
FROM wechat_event
WHERE effective_occurred_at >= #{s}
  AND effective_occurred_at < #{e}
  AND received_at < #{cutoff}

SELECT event_type AS eventType,
       COUNT(*) AS events,
       COUNT(DISTINCT open_id) AS uniqueUsers
FROM wechat_event
WHERE effective_occurred_at >= #{s}
  AND effective_occurred_at < #{e}
  AND received_at < #{cutoff}
GROUP BY event_type

SELECT qr_scene AS label,
       COUNT(*) AS events,
       COUNT(DISTINCT open_id) AS uniqueUsers
FROM wechat_event
WHERE effective_occurred_at >= #{s}
  AND effective_occurred_at < #{e}
  AND received_at < #{cutoff}
  AND event_type IN ('SUBSCRIBE', 'SCAN')
GROUP BY qr_scene

SELECT menu_key AS label,
       COUNT(*) AS events,
       COUNT(DISTINCT open_id) AS uniqueUsers
FROM wechat_event
WHERE effective_occurred_at >= #{s}
  AND effective_occurred_at < #{e}
  AND received_at < #{cutoff}
  AND event_type = 'MENU_CLICK'
GROUP BY menu_key

SELECT menu_url AS label,
       COUNT(*) AS events,
       COUNT(DISTINCT open_id) AS uniqueUsers
FROM wechat_event
WHERE effective_occurred_at >= #{s}
  AND effective_occurred_at < #{e}
  AND received_at < #{cutoff}
  AND event_type = 'MENU_VIEW'
GROUP BY menu_url

SELECT raw_event AS rawEvent,
       menu_key AS eventKey,
       COUNT(*) AS events,
       COUNT(DISTINCT open_id) AS uniqueUsers
FROM wechat_event
WHERE effective_occurred_at >= #{s}
  AND effective_occurred_at < #{e}
  AND received_at < #{cutoff}
  AND event_type = 'MENU_OTHER'
GROUP BY raw_event, menu_key

SELECT COUNT(*)
FROM wechat_event
WHERE effective_occurred_at >= #{s}
  AND effective_occurred_at < #{e}
  AND received_at < #{cutoff}
  AND event_type = 'LOCATION'

SELECT COUNT(DISTINCT open_id)
FROM wechat_event
WHERE effective_occurred_at >= #{s}
  AND effective_occurred_at < #{e}
  AND received_at < #{cutoff}
  AND event_type = 'LOCATION'

SELECT COUNT(*)
FROM wechat_event
WHERE effective_occurred_at >= #{s}
  AND effective_occurred_at < #{e}
  AND received_at < #{cutoff}
  AND anomalous_timestamp = TRUE

SELECT id, report_date, version, window_start, window_end,
       data_cutoff_at, snapshot_json, created_at
FROM daily_report
WHERE report_date = #{reportDate}
  AND version = #{version}

SELECT MAX(version)
FROM daily_report
WHERE report_date = #{reportDate}
